export function inversions(xs: number[]): number {
  let count = 0;
  for (let i = 0; i < xs.length; i++) {
    const x = xs[i];
    for (let j = i + 1; j < xs.length; j++) {
      if (xs[j] <= x) {
        count++;
      }
    }
  }
  return count;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { inversions } from "./inversions.js";

test("inversions", () => {
  assert.equal(inversions([3, 1, 2]), 2);
  assert.equal(inversions([2, 2, 1]), 2);
  assert.equal(inversions([5, 4, 3, 2, 1]), 10);
  assert.equal(inversions([]), 0);
});
